/*
 * Service Worker removal migration for the former Chirpy offline cache.
 * Keep this endpoint available so dormant clients can update, purge, and
 * unregister their old worker when they next visit the site.
 */

const CHIRPY_CACHE_PREFIX = 'chirpy-';

self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const cacheNames = await caches.keys();
      await Promise.all(
        cacheNames
          .filter((name) => name.startsWith(CHIRPY_CACHE_PREFIX))
          .map((name) => caches.delete(name))
      );

      await self.clients.claim();
      await self.registration.unregister();

      const windows = await self.clients.matchAll({ type: 'window' });
      await Promise.all(
        windows.map((client) => client.navigate(client.url).catch(() => undefined))
      );
    })()
  );
});
